//
// Culture levels in ascending order — a city clears a wonder's prereq
// when its own level's index is >= the prereq's.
export const CULTURE_LEVELS: readonly string[] = [
	"CULTURE_WEAK",
	"CULTURE_DEVELOPING",
	"CULTURE_STRONG",
	"CULTURE_LEGENDARY",
];

// Wonder (an improvement flagged <bWonder>) → the culture level a city
// must have reached to build it. Wonders have no tech prereq, so this is
// the whole gate.
